"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["13322"],{69807(e,t,n){n.d(t,{Ay:()=>r,RM:()=>a});var s=n(74848),i=n(28453);let a=[];function o(e){let t={a:"a",blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"cctv-dont-mistake-shamelessness-for-entertainment",children:"CCTV, Don't Mistake Shamelessness for Entertainment!"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2006/4/10 18:05:28"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:'Happened to watch TV today, and it was CCTV3, apparently a new program, something like "A Century of Chinese Music." It included a line: "In the last 20 years of the last century, Chinese music reached its pinnacle." If this so-called pinnacle reached its pinnacle within the comprehensively popularized linguistic context, then go ahead and pinnacle all you want. But if standing within the serious context they claim to represent, then CCTV, having just been shameless using General Shi, has once again world-historically lied with ever-increasing shamelessness!'}),"\n",(0,s.jsx)(t.p,{children:'For the Germans, their greatest music was written by Bach, Beethoven, and others. Even a garbage place like America wouldn\'t be shameless enough to forget that their father of music is Gershwin! I ask you: in the last 20 years of the last century, what Chinese musical work surpassed the "Yellow River Cantata"? Though "The Butterfly Lovers" is rather annoying, did any Chinese concerto from the last 20 years of the century surpass it?'}),"\n",(0,s.jsx)(t.p,{children:'Don\'t think that just because cinema had the garbage Fifth Generation directors, the so-called avant-garde composers in music like Tan, Wang, Guo, and their ilk became a pinnacle. The first 80 years of the last century weren\'t great for Chinese symphonic music, and the last 20 years didn\'t produce anything good either -- apart from the boasting, of course. As for art songs, like those by Zhao, Huang, Qing Zhu, and others -- works like "How Can I Not Think of Him," "The Great River Flows East," "I Live at the Head of the Yangtze" -- and works like "On the Jialing River," did the last 20 years of the century produce anything to surpass them?'}),"\n",(0,s.jsx)(t.p,{children:'In popular songs, is there anything that surpasses "My Motherland"? In military songs, anything better than "I Love Wuzhi Mountain, I Love Wanquan River"? In the hymn category, anything exceeding "Song of Praise" or "Ode to Beijing"? In folk-style opera, anything surpassing "The White-Haired Girl" or "Little Erhei\'s Wedding"? Even in the domain of folk instrumental music, did the last 20 years produce any works approaching the classics of Cantonese music, Jiangnan silk-and-bamboo, and the like? Anything surpassing Liu Tianhua? Don\'t think that just because those who messed around with Chinese music in the last 20 years now have the power of discourse, they can shamelessly spout nonsense. Destroy all their garbage works, and pieces like "Moon Reflected in the Erquan Spring" will still be considered classics.'}),"\n",(0,s.jsx)(t.p,{children:"Musical works are written with life, not blown out through the mouth -- listen to the music of Bach, Beethoven, and Schubert and you'll understand. Chinese music, aside from ancient pieces and folk songs, has a significant gap compared to the world's top level. But China's best modern works are absolutely not from the last 20 years, and the last 20 years were absolutely not the pinnacle of Chinese music. This is beyond doubt."}),"\n",(0,s.jsx)(t.p,{children:"Listen to this art song from the 1930s. Nothing from the last 20 years of the century, including symphonies, can surpass it! CCTV, don't mistake shamelessness for entertainment!"}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.a,{href:"https://resources.chzhshch.blog/music/%E5%98%89%E9%99%B5%E6%B1%9F%E4%B8%8A.mp3",children:"On the Jialing River"})}),"\n",(0,s.jsx)("audio",{controls:!0,children:(0,s.jsx)("source",{src:"https://resources.chzhshch.blog/music/\u5609\u9675\u6C5F\u4E0A.mp3"})})]})}function r(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(o,{...e})}):o(e)}},4708(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>d,frontMatter:()=>r,contentTitle:()=>h,toc:()=>l,assets:()=>c});var s=JSON.parse('{"id":"timeline/music/tocctv","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/music/tocctv.md","sourceDirName":"timeline/music","slug":"/timeline/music/tocctv","permalink":"/en/timeline/music/tocctv","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"tocctv","title":"","hide_table_of_contents":true,"sidebar_label":"CCTV: Don\'t Mistake Shamelessness for Entertainment! (2006/4/10 18:05:28)"},"sidebar":"timelineSidebar","previous":{"title":"Bush: The True Disciple of Mao Zedong! (2006/4/9 22:49:42)","permalink":"/en/timeline/economics/bush"},"next":{"title":"The Greatest Risk to Chinese Society: Hu Hansan Is Coming Back! (2006/4/10 21:46:14)","permalink":"/en/timeline/economics/huhan3"}}'),i=n(74848),a=n(28453),o=n(69807);let r={id:"tocctv",title:"",hide_table_of_contents:!0,sidebar_label:"CCTV: Don't Mistake Shamelessness for Entertainment! (2006/4/10 18:05:28)"},h,c={},l=[...o.RM];function u(e){return(0,i.jsx)(o.Ay,{})}function d(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(96540);let i={},a=s.createContext(i);function o(e){let t=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),s.createElement(a.Provider,{value:t},e.children)}}}]);